<?php
require __DIR__.'/app/bootstrap.php';$u=require_user(false);require_commerce();$title=t('My reviews');
$foodReviews=all('SELECT r.*,s.id store_id,m.id existing_product,m.status product_status FROM product_reviews r LEFT JOIN seller_applications s ON s.user_id=r.seller_id LEFT JOIN menu_items m ON m.id=r.product_id WHERE r.user_id=? ORDER BY r.updated_at DESC',[$u['id']]);
$shopReviews=update02_ready()?all('SELECT r.*,s.id store_id,s.business_name FROM seller_reviews r LEFT JOIN seller_applications s ON s.user_id=r.seller_id WHERE r.user_id=? ORDER BY r.updated_at DESC',[$u['id']]):[];
require ROOT.'/app/header.php'; ?>
<main class="page shell medium" id="main"><div class="page-heading"><span class="heading-kicker"><?=e(t('YOUR VOICE IN THE COMMUNITY'))?></span><h1><?=e(t('My Reviews'))?></h1><p><?=e(t('Find the food and shop reviews you’ve shared.'))?></p></div><section><h2><?=e(t('Food reviews'))?></h2><div class="review-list"><?php if(!$foodReviews): ?><div class="panel"><p><?=e(t('Once an order is collected or delivered, you can review its dishes from My Orders.'))?></p><a class="pill" href="<?=e(url('orders.php'))?>"><?=e(t('My Orders →'))?></a></div><?php endif ?><?php foreach($foodReviews as $review): ?><article class="panel padded"><div class="order-meta"><span class="chip"><?=e(t('Verified order'))?></span><?php if(!$review['existing_product']||$review['product_status']==='archived'): ?><span><?=e(t('No longer offered'))?></span><?php endif ?></div><h3><?=e($review['product_name'])?></h3><p class="hint"><?=e($review['shop_name'])?> · <?=e(local_time($review['updated_at'],'d M Y'))?></p><?=rating_html((float)$review['rating'],1)?><p><?=nl2br(e($review['review_text']))?></p><div class="row-actions"><a class="pill compact" href="<?=e(url('review-food.php?item='.$review['order_item_id']))?>"><?=e(t('Edit Review'))?></a><?php if($review['store_id']): ?><a class="pill compact" href="<?=e(url('restaurant.php?id='.$review['store_id'].'#food-reviews'))?>"><?=e(t('View Shop'))?></a><?php endif ?></div></article><?php endforeach ?></div></section>
<section class="space-top"><h2><?=e(t('Shop reviews'))?></h2><div class="review-list"><?php if(!$shopReviews): ?><div class="panel"><p><?=e(t('You haven’t reviewed any shops yet.'))?></p><a href="<?=e(url('restaurants.php'))?>"><?=e(t('Explore Restaurants →'))?></a></div><?php endif ?><?php foreach($shopReviews as $review): ?><article class="panel padded"><h3><?=e($review['business_name']??'Restaurant')?></h3><?=rating_html((float)$review['rating'],1)?><p><?=nl2br(e($review['review_text']))?></p><p class="hint"><?=e(local_time($review['updated_at'],'d M Y'))?></p><?php if($review['store_id']): ?><a class="pill compact" href="<?=e(url('restaurant.php?id='.$review['store_id'].'#reviews'))?>"><?=e(t('View or Edit Review →'))?></a><?php endif ?></article><?php endforeach ?></div></section></main><?php require ROOT.'/app/footer.php'; ?>
